#![cfg(not(target_arch="wasm32"))]
use semio_framework_job::*;use semio_framework_job_worker::{WorkerJobOutcome,WorkerJobPoll,WorkerJobSession,WorkerJobSessionPreparation,OriginalWorkerFixtureCaller};use semio_framework_job_worker_authority::{BatchDriveConfig,BatchJobParams};
use semio_framework_ui::wgpu::{ClipboardIoJob,ClipboardIoJobInitializer};
#[global_allocator]
static ALLOCATOR:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn clock()->Option<u64>{Some(1000)}
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}
fn grant(law:&serde_json::Value)->RetainedCloneGrant{let value=&law["policy"];RetainedCloneGrant{maximum_items:value["items"].as_u64().unwrap()as usize,maximum_copy_bytes:value["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:value["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:value["release"].as_u64().unwrap()as usize,maximum_depth:value["depth"].as_u64().unwrap()as usize}}
fn prepare(caller:&mut OriginalJobFixtureCaller,grant:RetainedCloneGrant,initializer:&mut ClipboardIoJobInitializer)->WorkerJobSession<ClipboardIoJob>{
 let mut params=Some(BatchJobParams{operation:OperationId(71),generation:Generation(3),cancel:caller.admit_alias(grant),config:BatchDriveConfig{retained:grant,site:"original_clipboard_fixture",stage:InteractiveStage::InteractiveStep,fuel_per_step:64,step_budget_us:500},now_us:clock});
 let Some((mut preparation,_))=caller.turn(grant,|cx|WorkerJobSessionPreparation::try_begin(initializer,&mut params,cx).map_err(OriginalTurnFailure::from)).unwrap()else{panic!("authentic original policy funds final storage")};
 for _ in 0..4096{let((session,progress),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant,|cx|preparation.advance(initializer,&mut params,cx).map_err(OriginalTurnFailure::from)).unwrap());assert_eq!(progress,caller.receipt());assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));if let Some(session)=session{assert!(preparation.terminal_is_empty());assert!(params.is_none());return session}}
 panic!("bounded original preparation must finish")
}
fn acknowledge(caller:&mut OriginalJobFixtureCaller,grant:RetainedCloneGrant,outcome:&mut WorkerJobOutcome<ClipboardIoJob>){for _ in 0..4{if outcome.outcome_descriptor().is_none(){return}caller.turn(grant,|cx|{let step=outcome.acknowledge_outcome(cx.retained_grant());cx.consume_retained(step.progress())?;cx.consume_fuel(step.progress().copied_items as u64);Ok(())}).unwrap()}assert!(outcome.outcome_descriptor().is_none())}
fn close(caller:&mut OriginalJobFixtureCaller,grant:RetainedCloneGrant,session:&mut WorkerJobSession<ClipboardIoJob>){for _ in 0..4096{if session.terminal_is_empty(){return}let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.close_owner(grant,session).unwrap());assert_eq!(step.progress(),caller.receipt());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}panic!("original session closure must finish")}
#[test]
fn original_clipboard_final_storage_denial_preserves_text_and_cancelled_descriptor(){
 let law=fixture();let grant=grant(&law);let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),grant,clock,1500,64);let expected:String=serde_json::from_value(law["text"].clone()).unwrap();let mut text=String::with_capacity(law["capacity"].as_u64().unwrap()as usize);text.push_str(&expected);let pointer=text.as_ptr();let capacity=text.capacity();let mut initializer=ClipboardIoJobInitializer::write(text);
 let demand=initializer.initialization_demand(4096).unwrap();assert!(demand.copy_bytes>0&&demand.copy_bytes<=4096);assert!(std::mem::size_of::<ClipboardIoJob>()>demand.copy_bytes);
 let mut target=std::mem::MaybeUninit::<ClipboardIoJob>::uninit();let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||unsafe{initializer.initialize_step(&mut target,RetainedCloneGrant{maximum_copy_bytes:0,..grant}).unwrap()});assert!(!step.complete);assert_eq!(step.progress,RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(initializer.original_write_text().unwrap().as_ptr(),pointer);assert_eq!(initializer.original_write_text().unwrap().capacity(),capacity);
 let mut session=prepare(&mut caller,grant,&mut initializer);assert!(initializer.initialization_input_is_empty());caller.cancel().cancel_now();let(ticket,kind)=caller.turn(grant,|cx|session.try_step_on_original_caller(cx)).unwrap().unwrap();assert_eq!(kind,WorkerJobPoll::Terminal);let issued=session.take_retained_step_receipt().unwrap().unwrap();assert_eq!(issued.1,caller.receipt());let mut outcome=session.take_outcome(ticket).or_else(|_|session.take_terminal()).unwrap();assert_eq!(outcome.job().original_write_text().unwrap().as_ptr(),pointer);assert_eq!(outcome.job().original_write_text().unwrap().capacity(),capacity);assert!(matches!(outcome.outcome().unwrap(),Some(JobOutcomeView::Cancelled{..})));acknowledge(&mut caller,grant,&mut outcome);outcome.begin_close();close(&mut caller,grant,&mut session);drop(session);caller.retire(grant);eprintln!("[DEBUG] Original clipboard final storage quotes initialized metadata only, preserves exact original String under denial, ACKs original cancelled descriptor, and closes every actual native allocation under unchanged4096 policy");
}
#[test]
fn original_clipboard_read_fault_borrows_before_ack_and_paid_terminal_close(){
 let law=fixture();let grant=grant(&law);let expected:String=serde_json::from_value(law["expectedDiagnostic"].clone()).unwrap();let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),grant,clock,1500,64);let mut initializer=ClipboardIoJobInitializer::read();let mut session=prepare(&mut caller,grant,&mut initializer);
 for _ in 0..4096{let Some((ticket,kind))=caller.turn(grant,|cx|session.try_step_on_original_caller(cx)).unwrap()else{continue};let(_,receipt)=session.take_retained_step_receipt().unwrap().unwrap();assert_eq!(receipt,caller.receipt());let mut outcome=if kind==WorkerJobPoll::Terminal{session.take_terminal().unwrap()}else{session.take_outcome(ticket).unwrap()};if kind==WorkerJobPoll::Terminal{let(view,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||outcome.outcome().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let Some(JobOutcomeView::Fault{detail,..})=view else{panic!("existing bounded read producer must publish its actual fault")};assert_eq!(detail.page(0).unwrap(),expected.as_bytes());assert!(ClipboardIoJob::read_candidate(&JobOutcomeView::Fault{detail,admission:outcome.outcome_descriptor().unwrap().admission()}).is_none());acknowledge(&mut caller,grant,&mut outcome);outcome.begin_close();close(&mut caller,grant,&mut session);drop(session);caller.retire(grant);eprintln!("[DEBUG] Original native clipboard bounded read fault borrowed through exact original caller/ledger, acknowledged once, and physically retired; successful platform read remains unsupported");return}
 if outcome.outcome_descriptor().is_some(){acknowledge(&mut caller,grant,&mut outcome)}outcome.resume().ok().unwrap();}
 panic!("bounded original read diagnostic must finish")
}
